    {"id": "wh4_16", "level": 4, "term": "구텐베르크", "definition": "금속활자와 인쇄기를 발명하여 성경과 루터의 반박문을 대량 보급해 종교개혁을 촉발함."},
    {"id": "wh4_17", "level": 4, "term": "마르틴루터", "definition": "교황청의 면죄부 판매를 비판하는 95개조 반박문을 비텐베르크 성당 문에 붙인 종교개혁가."},
    {"id": "wh4_18", "level": 4, "term": "반박문", "definition": "루터가 오직 믿음과 오직 성경만으로 구원을 얻는다고 교황청의 면벌부를 논박한 글."},
    {"id": "wh4_19", "level": 4, "term": "칼뱅", "definition": "구원받을 자는 이미 신에 의해 미리 정해져 있다는 예정설을 주장하고 근검절약을 강조함."},
    {"id": "wh4_20", "level": 4, "term": "예정설", "definition": "인간의 구원 여부는 행위가 아니라 오직 하나님의 절대적 주권으로 미리 결정되어 있다는 교리."},
    {"id": "wh4_21", "level": 4, "term": "낭트칙령", "definition": "프랑스 앙리 4세가 위그노(신교도)들에게 종교의 자유를 허용하여 종교 내전을 종식시킨 칙령."},
    {"id": "wh4_22", "level": 4, "term": "대항해시대", "definition": "15세기 후반 포르투갈과 스페인이 아시아로 가는 신항로를 개척하며 전 세계로 뻗어나간 시대."},
    {"id": "wh4_23", "level": 4, "term": "콜럼버스", "definition": "스페인 이사벨 여왕의 후원을 받아 대서양을 건너 아메리카 대륙에 도달한 탐험가."},
    {"id": "wh4_24", "level": 4, "term": "마젤란", "definition": "남미 남단의 해협을 통과하고 태평양을 건너 인류 최초로 지구를 한 바퀴 도는 세계일주에 성공함."},
    {"id": "wh4_25", "level": 4, "term": "바스코다가마", "definition": "아프리카 대륙 남단의 희망봉을 돌아 인도 캘리컷에 도달하는 인도 신항로를 개척함."},
    {"id": "wh4_26", "level": 4, "term": "에라스무스", "definition": "'우신예찬'을 통해 타락한 교황과 교회의 위선을 날카롭게 풍자한 네덜란드의 인문학자."},
    {"id": "wh4_27", "level": 4, "term": "토머스모어", "definition": "사유재산이 없고 모든 사람이 평등하게 일하며 행복한 이상향을 그린 '유토피아'를 저술함."},
    {"id": "wh4_28", "level": 4, "term": "갈릴레이", "definition": "망원경으로 목성의 위성과 달의 분화구를 관측하고 지동설을 지지하여 종교재판을 받음."},
    {"id": "wh4_29", "level": 4, "term": "코페르니쿠스", "definition": "지구가 우주의 중심이라는 천동설을 뒤엎고 태양 중심의 지동설을 과학적으로 제창함."},
    {"id": "wh4_30", "level": 4, "term": "아즈텍제국", "definition": "멕시코 고원에 테노치티틀란을 수도로 세운 문명으로 스페인 코르테스에 의해 멸망함."},
    {"id": "wh4_31", "level": 4, "term": "잉카제국", "definition": "안데스 산맥 마추픽추를 건설하고 태양신을 숭배했으나 스페인 피사로에게 멸망한 문명."},

    # Lv.5 (+21)
    {"id": "wh5_11", "level": 5, "term": "절대왕정", "definition": "봉건 영주를 굴복시키고 관료제와 상비군을 기반으로 군주가 절대 권력을 휘두른 정치 형태."},
    {"id": "wh5_12", "level": 5, "term": "왕권신수설", "definition": "국왕의 권력은 신으로부터 직접 부여받은 것이므로 백성은 무조건 복종해야 한다는 이론."},
    {"id": "wh5_13", "level": 5, "term": "루이십사세", "definition": "'짐이 곧 국가다'라고 선언하고 베르사유 궁전을 지어 절대왕정의 절정을 이룬 프랑스 태양왕."},
    {"id": "wh5_14", "level": 5, "term": "베르사유궁", "definition": "루이 14세가 권력을 과시하기 위해 파리 근교에 지은 거울의 방과 정원으로 유명한 바로크 궁전."},
    {"id": "wh5_15", "level": 5, "term": "중상주의", "definition": "국부의 원천을 금과 은의 축적으로 보고 수출을 장려하고 수입을 억제하며 식민지를 수탈함."},
    {"id": "wh5_16", "level": 5, "term": "무적함대", "definition": "스페인 펠리페 2세가 영국을 침공하기 위해 보냈으나 엘리자베스 1세의 영국 해군에 패배함."},
    {"id": "wh5_17", "level": 5, "term": "엘리자베스", "definition": "'나는 국가와 결혼했다'며 종교 갈등을 수습하고 무적함대를 격파해 대영제국의 번영을 연 여왕."},
    {"id": "wh5_18", "level": 5, "term": "동인도회사", "definition": "영국과 네덜란드가 아시아 식민지 무역 독점과 군사적 지배를 위해 세운 국책 특허 회사."},
    {"id": "wh5_19", "level": 5, "term": "표트르대제", "definition": "서유럽의 기술과 제도를 적극 수용하여 상트페테르부르크를 건설하고 러시아를 강국으로 키움."},
    {"id": "wh5_20", "level": 5, "term": "청교도혁명", "definition": "1642년 전제 정치를 일삼던 찰스 1세를 크롬웰의 의회파 군대가 처형하고 공화정을 수립한 혁명."},
    {"id": "wh5_21", "level": 5, "term": "크롬웰", "definition": "철기대를 이끌고 왕당파를 꺾은 뒤 호국경에 올라 엄격한 청교도적 독재 정치를 펼친 인물."},
    {"id": "wh5_22", "level": 5, "term": "명예혁명", "definition": "1688년 피 한 방울 흘리지 않고 제임스 2세를 폐위하고 윌리엄과 메리를 공동 왕으로 세운 혁명."},
    {"id": "wh5_23", "level": 5, "term": "권리장전", "definition": "1689년 영국 의회가 제정하여 '의회의 동의 없는 과세와 법 집행을 금지'한 입헌군주제의 초석."},
    {"id": "wh5_24", "level": 5, "term": "입헌군주제", "definition": "헌법에 의해 군주의 권력이 제한되고 의회가 중심이 되어 국정을 이끄는 민주 정치 제도."},
    {"id": "wh5_25", "level": 5, "term": "미국독립혁명", "definition": "영국의 가혹한 세금 부과에 맞서 13개 식민지가 전쟁을 벌여 민주공화국을 세운 독립 혁명."},
    {"id": "wh5_26", "level": 5, "term": "보스턴차사건", "definition": "1773년 보스턴항에 정박 중인 동인도회사 배에 인디언으로 변장한 시민들이 차 상자를 바다에 던짐."},
    {"id": "wh5_27", "level": 5, "term": "독립선언서", "definition": "1776년 7월 4일 토머스 제퍼슨이 초안하여 인간의 양도할 수 없는 생명, 자유, 행복 추구권을 선포함."},
    {"id": "wh5_28", "level": 5, "term": "조지워싱턴", "definition": "독립전쟁의 총사령관으로 승리를 이끌고 초대 미국 대통령으로 추대되어 건국의 아버지가 됨."},
    {"id": "wh5_29", "level": 5, "term": "토머스제퍼슨", "definition": "독립선언서를 기초하고 루이지애나를 매입하여 미국의 영토를 두 배로 넓힌 제3대 대통령."},
    {"id": "wh5_30", "level": 5, "term": "대륙회의", "definition": "영국의 탄압에 맞서 13개 식민지 대표들이 필라델피아에 모여 독립전쟁을 결의한 대표자 회의."},
    {"id": "wh5_31", "level": 5, "term": "연방주의자", "definition": "강력한 중앙 연방정부 수립을 지지하며 미국 헌법 제정을 주도한 해밀턴, 매디슨 등."},

    # Lv.6 (+21)
    {"id": "wh6_11", "level": 6, "term": "프랑스혁명", "definition": "1789년 자유, 평등, 박애의 기치 아래 절대왕정과 봉건적 신분제를 타파한 시민 대혁명."},
    {"id": "wh6_12", "level": 6, "term": "구제도의모순", "definition": "소수의 성직자와 귀족이 토지와 면세 특권을 누리고 대다수 제3신분 평민만 무거운 세금을 짐(앙시앵 레짐)."},
    {"id": "wh6_13", "level": 6, "term": "바스티유", "definition": "1789년 7월 14일 분노한 파리 시민들이 무기를 탈취하기 위해 습격한 전제정치의 상징 감옥."},
    {"id": "wh6_14", "level": 6, "term": "인권선언", "definition": "라파예트 등이 초안하여 '인간은 자유롭고 평등한 권리를 가지고 태어난다'고 선언한 문서."},
    {"id": "wh6_15", "level": 6, "term": "삼부회", "definition": "성직자, 귀족, 평민의 세 신분 대표로 구성된 프랑스 신분제 의회로 세금 문제를 둘러싸고 파행됨."},
    {"id": "wh6_16", "level": 6, "term": "테니스코트", "definition": "삼부회에서 쫓겨난 제3신분 대표들이 모여 헌법이 제정될 때까지 해산하지 않겠다고 선서함."},
    {"id": "wh6_17", "level": 6, "term": "단두대", "definition": "프랑스 혁명기 루이 16세와 마리 앙투아네트 등 수많은 귀족과 정적을 처형한 사형 기구(기요틴)."},
    {"id": "wh6_18", "level": 6, "term": "자코뱅파", "definition": "로베스피에르를 중심으로 급진적 공화정과 민중 권익을 주장한 혁명기 좌파 정치 집단."},
    {"id": "wh6_19", "level": 6, "term": "로베스피에르", "definition": "공안위원회를 이끌며 반혁명 분자를 단두대에서 처형하는 공포정치를 펼치다 결국 처형당함."},
    {"id": "wh6_20", "level": 6, "term": "공포정치", "definition": "혁명 정부가 국내외 위기를 타개하기 위해 재판 없이 공포 분위기 속에 수만 명을 처형한 독재."},
    {"id": "wh6_21", "level": 6, "term": "테르미도르", "definition": "1794년 로베스피에르의 공포정치에 지친 온건파가 쿠데타를 일으켜 로베스피에르를 축출한 반동."},
    {"id": "wh6_22", "level": 6, "term": "나폴레옹", "definition": "쿠데타로 정권을 잡고 황제에 올랐으며 유럽 대륙을 제패하고 자유주의 법전을 전파한 군사 천재."},
    {"id": "wh6_23", "level": 6, "term": "나폴레옹법전", "definition": "법 앞의 평등, 종교의 자유, 사유재산권 보장 등 프랑스 혁명의 성과를 집대성한 근대 민법전."},
    {"id": "wh6_24", "level": 6, "term": "트라팔가르", "definition": "1805년 영국 넬슨 제독이 나폴레옹의 프랑스·스페인 연합 함대를 스페인 연안에서 전멸시킨 해전."},
    {"id": "wh6_25", "level": 6, "term": "대륙봉쇄령", "definition": "나폴레옹이 해상 패권을 쥔 영국을 경제적으로 고립시키기 위해 유럽 대륙의 영국 무역을 금지함."},
    {"id": "wh6_26", "level": 6, "term": "러시아원정", "definition": "대륙봉쇄령을 어긴 러시아를 응징하기 위해 60만 대군으로 침공했으나 혹한과 초토화 작전으로 궤멸됨."},
    {"id": "wh6_27", "level": 6, "term": "워털루전투", "definition": "엘바섬을 탈출해 복위한 나폴레옹의 100일 천하를 웰링턴의 영국·프로이센 연합군이 완전히 끝장낸 전투."},
    {"id": "wh6_28", "level": 6, "term": "빈회의", "definition": "나폴레옹 몰락 후 유럽 국경을 혁명 이전의 절대왕정 상태로 되돌리기 위해 열린 보수 회의."},
    {"id": "wh6_29", "level": 6, "term": "메테르니히", "definition": "오스트리아 재상으로 빈 회의를 주도하여 유럽의 자유주의와 민족주의 운동을 철저히 탄압함."},
    {"id": "wh6_30", "level": 6, "term": "칠월혁명", "definition": "1830년 샤를 10세의 반동 전제정치에 맞서 파리 시민들이 바리케이드를 치고 루이 필리프를 왕으로 세움."},
    {"id": "wh6_31", "level": 6, "term": "이월혁명", "definition": "1848년 노동자와 시민들이 선거권 확대를 요구하며 봉기해 7월 왕정을 무너뜨리고 제2공화정을 세움."},

    # Lv.7 (+21)
    {"id": "wh7_11", "level": 7, "term": "산업혁명", "definition": "18세기 후반 영국에서 증기기관과 기계의 발명으로 가내수공업에서 공장제 기계공업으로 전환된 변혁."},
    {"id": "wh7_12", "level": 7, "term": "제임스와트", "definition": "뉴커먼의 증기기관을 획기적으로 개량하여 공장과 기차의 핵심 동력원으로 보급한 발명가."},
    {"id": "wh7_13", "level": 7, "term": "방적기", "definition": "목화솜에서 실을 대량으로 빠르게 자아내는 기계로 면직물 공업의 폭발적 성장을 이끎."},
    {"id": "wh7_14", "level": 7, "term": "철도혁명", "definition": "스티븐슨이 증기기관차를 발명하여 대량의 원자재와 인력을 초고속으로 수송하며 시장을 전국화함."},
    {"id": "wh7_15", "level": 7, "term": "자본주의", "definition": "생산수단을 소유한 자본가가 이윤 추구를 목적으로 노동자를 고용하여 상품을 생산하는 경제 체제."},
    {"id": "wh7_16", "level": 7, "term": "아담스미스", "definition": "국부론을 저술하여 자유방임주의와 '보이지 않는 손'에 의한 시장 경제 원리를 정립한 경제학의 아버지."},
    {"id": "wh7_17", "level": 7, "term": "보이지않는손", "definition": "개인이 사적 이익을 추구하더라도 시장 가격 기구를 통해 사회 전체의 번영이 조화롭게 달성됨."},
    {"id": "wh7_18", "level": 7, "term": "기계파괴운동", "definition": "산업혁명 초기 기계에 밀려 일자리를 잃고 임금이 깎인 노동자들이 기계를 부순 러다이트 운동."},
    {"id": "wh7_19", "level": 7, "term": "차티스트운동", "definition": "1830~40년대 영국 노동자들이 인민헌장을 선포하고 보통선거권과 비밀투표를 요구한 참정권 운동."},
    {"id": "wh7_20", "level": 7, "term": "제국주의", "definition": "자본주의의 고도화로 독점자본과 상품 시장, 원료 공급지를 찾아 군사력으로 후진국을 식민지화함."},
    {"id": "wh7_21", "level": 7, "term": "아프리카분할", "definition": "1884년 베를린 회의에서 유럽 열강들이 아프리카 부족 경계를 무시하고 자를 대고 국경을 그어 나눔."},
    {"id": "wh7_22", "level": 7, "term": "종단정책", "definition": "영국이 이집트 카이로에서 남아프리카 케이프타운을 철도로 연결하려던 남북 식민지 팽창 정책."},
    {"id": "wh7_23", "level": 7, "term": "횡단정책", "definition": "프랑스가 서아프리카 세네갈에서 동아프리카 지부티를 연결하려던 동서 식민지 팽창 정책."},
    {"id": "wh7_24", "level": 7, "term": "파쇼다사건", "definition": "1898년 수단의 파쇼다에서 영국의 종단 정책과 프랑스의 횡단 정책이 군사적으로 정면충돌한 사건."},
    {"id": "wh7_25", "level": 7, "term": "아편전쟁", "definition": "영국이 은 유출을 막기 위해 청나라에 마약 아편을 밀수출하다 발생하자 함포로 공격한 침략 전쟁."},
    {"id": "wh7_26", "level": 7, "term": "난징조약", "definition": "아편전쟁에서 패한 청나라가 홍콩을 영국에 할양하고 5개 항구를 강제 개항한 불평등 조약."},
    {"id": "wh7_27", "level": 7, "term": "태평천국운동", "definition": "홍수전이 멸만흥한과 토지 균등 분배를 외치며 만주족 청나라에 맞서 14년간 봉기한 농민 전쟁."},
    {"id": "wh7_28", "level": 7, "term": "세포이항쟁", "definition": "동인도회사의 인도인 용병(세포이)들이 소기름 탄약포 지급에 반발하여 일으킨 전 인도적 반영 봉기."},
    {"id": "wh7_29", "level": 7, "term": "메이지유신", "definition": "1868년 일본이 도쿠가와 막부를 무너뜨리고 천황 중심의 서양식 근대 국가와 제국주의로 변신함."},
    {"id": "wh7_30", "level": 7, "term": "신해혁명", "definition": "1911년 쑨원이 삼민주의를 내세워 청나라를 무너뜨리고 아시아 최초의 공화국인 중화민국을 세움."},
    {"id": "wh7_31", "level": 7, "term": "삼민주의", "definition": "쑨원이 제창한 민족, 민권, 민생의 세 가지 정치 강령으로 중국 근대 혁명의 나침반이 됨."},

    # Lv.8 (+21)
    {"id": "wh8_11", "level": 8, "term": "사라예보사건", "definition": "1914년 보스니아 사라예보에서 세르비아 청년이 오스트리아 황태자 부부를 저격해 1차대전이 발발함."},
    {"id": "wh8_12", "level": 8, "term": "삼국동맹", "definition": "비스마르크의 주도로 독일, 오스트리아-헝가리, 이탈리아가 맺은 제1차 세계대전 이전의 동맹."},
    {"id": "wh8_13", "level": 8, "term": "삼국협상", "definition": "독일의 팽창을 막기 위해 영국, 프랑스, 러시아가 맺은 3국 군사 협력 체제."},
    {"id": "wh8_14", "level": 8, "term": "참호전", "definition": "기관총과 철조망으로 인해 양측 군대가 땅을 파고 숨어 수개월간 수십만 명이 희생된 소모전."},
    {"id": "wh8_15", "level": 8, "term": "유보트", "definition": "독일 해군이 연합국의 해상 보급선을 차단하기 위해 실전에 대량 투입한 악명 높은 잠수함."},
    {"id": "wh8_16", "level": 8, "term": "무제한잠수함", "definition": "독일이 지정 해역을 통과하는 모든 중립국 상선까지 사전 경고 없이 격침시키기로 선언한 작전."},
    {"id": "wh8_17", "level": 8, "term": "베르사유조약", "definition": "1919년 파리 강화회의에서 패전국 독일에 막대한 배상금과 군비 축소, 영토 상실의 멍에를 씌운 조약."},
    {"id": "wh8_18", "level": 8, "term": "국제연맹", "definition": "미국 윌슨 대통령의 제안으로 세계 평화 유지를 위해 창설되었으나 군사 제재력이 없어 무력했던 기구."},
    {"id": "wh8_19", "level": 8, "term": "민족자결주의", "definition": "각 민족은 다른 민족의 간섭 없이 자신의 정치적 운명을 스스로 결정할 권리가 있다는 원칙."},
    {"id": "wh8_20", "level": 8, "term": "피의일요일", "definition": "1905년 상트페테르부르크에서 빵과 개혁을 요구하며 황제의 궁전으로 평화 행진하던 군중을 학살함."},
    {"id": "wh8_21", "level": 8, "term": "러시아혁명", "definition": "1917년 차르 전제정을 무너뜨리고 인류 최초의 사회주의 국가인 소련(소비에트 연방)을 세운 혁명."},
    {"id": "wh8_22", "level": 8, "term": "볼셰비키", "definition": "레닌이 이끈 러시아 사회민주노동당의 급진 다수파로 무장 봉기를 통해 소비에트 정권을 수립함."},
    {"id": "wh8_23", "level": 8, "term": "블라디미르레닌", "definition": "'모든 권력을 소비에트로'를 외치며 10월 혁명을 승리로 이끌고 소비에트 연방을 건설한 지도자."},
    {"id": "wh8_24", "level": 8, "term": "전시공산주의", "definition": "소련 내전기 동안 백군과의 전쟁을 치르기 위해 모든 기업을 국유화하고 농민 곡물을 강제 징발함."},
    {"id": "wh8_25", "level": 8, "term": "신경제정책", "definition": "내전 후 피폐해진 경제를 살리기 위해 일부 소규모 사유재산과 시장 경제를 허용한 레닌의 유화책(NEP)."},
    {"id": "wh8_26", "level": 8, "term": "트로츠키", "definition": "붉은군대를 창설하여 내전을 승리로 이끌고 영구혁명론을 주장했으나 스탈린에게 암살당한 혁명가."},
    {"id": "wh8_27", "level": 8, "term": "스탈린", "definition": "일국사회주의론을 내세워 정적들을 대숙청하고 강제 중공업화와 집단농장화를 밀어붙인 독재자."},
    {"id": "wh8_28", "level": 8, "term": "대숙청", "definition": "1930년대 스탈린이 자신의 권력을 절대화하기 위해 당, 군대, 지식인 수백만 명을 처형하고 유배 보냄."},
    {"id": "wh8_29", "level": 8, "term": "오개년계획", "definition": "소련이 국가 주도의 철강, 전력 등 중공업 위주로 경제를 급속도로 발전시킨 계획경제 체제."},
    {"id": "wh8_30", "level": 8, "term": "코민테른", "definition": "전 세계 노동자 혁명과 각국 공산당 활동을 지도하기 위해 모스크바에 설립된 국제 공산주의 조직."},
    {"id": "wh8_31", "level": 8, "term": "바이마르헌법", "definition": "1차대전 후 독일 공화국이 제정하여 노동 기본권과 사회보장권을 세계 최초로 명시한 선진적 헌법."},

    # Lv.9 (+21)
    {"id": "wh9_11", "level": 9, "term": "검은목요일", "definition": "1929년 10월 24일 뉴욕 월스트리트 주식시장이 대폭락하며 전 세계 대공황의 서막을 알린 날."},
    {"id": "wh9_12", "level": 9, "term": "세계대공황", "definition": "과잉생산과 주가 폭락으로 수많은 은행과 공장이 도산하고 수천만 실업자가 거리로 쏟아진 위기."},
    {"id": "wh9_13", "level": 9, "term": "루스벨트", "definition": "극심한 대공황 극복을 위해 정부의 강력한 시장 개입과 사회보장을 담은 뉴딜 정책을 시행한 미국 대통령."},
    {"id": "wh9_14", "level": 9, "term": "뉴딜정책", "definition": "자유방임주의를 버리고 테네시강 댐 건설 등 공공사업과 노동권 보장으로 구매력을 살린 정책."},
    {"id": "wh9_15", "level": 9, "term": "블록경제", "definition": "영국과 프랑스가 식민지들과 높은 관세 장벽을 쌓아 자국 경제만 보호하려던 배타적 경제권."},
    {"id": "wh9_16", "level": 9, "term": "파시즘", "definition": "개인의 자유를 전면 부정하고 국가와 민족의 영광만을 절대시하는 극단적인 국수주의 독재 이념."},
    {"id": "wh9_17", "level": 9, "term": "무솔리니", "definition": "검은셔츠단을 이끌고 로마 진군을 벌여 정권을 장악한 이탈리아 최초의 파시스트 독재자."},
    {"id": "wh9_18", "level": 9, "term": "나치즘", "definition": "히틀러가 이끈 독일 국가사회주의로 아리아 인종의 우월성과 유대인 학살을 부르짖은 극단적 광기."},
    {"id": "wh9_19", "level": 9, "term": "아돌프히틀러", "definition": "대공황의 혼란을 틈타 합법적으로 총리에 오른 뒤 2차 대전을 일으키고 홀로코스트를 저지른 전범."},
    {"id": "wh9_20", "level": 9, "term": "나의투쟁", "definition": "히틀러가 뮌헨 폭동 실패 후 감옥에서 쓴 책으로 인종주의적 편견과 동방 생존권(레벤스라움)을 밝힘."},
    {"id": "wh9_21", "level": 9, "term": "수권법", "definition": "1933년 독일 의회가 통과시켜 국회의 동의 없이 내각(히틀러)이 마음대로 법률을 제정할 수 있게 한 법."},
    {"id": "wh9_22", "level": 9, "term": "반유대주의", "definition": "유대인을 독일의 패전과 경제 파탄의 주범으로 몰아 사회적으로 배척하고 학살한 인종차별주의."},
    {"id": "wh9_23", "level": 9, "term": "뉘른베르크법", "definition": "1935년 나치가 제정하여 유대인의 시민권을 박탈하고 독일인과의 결혼 및 성관계를 금지한 법률."},
    {"id": "wh9_24", "level": 9, "term": "수정의밤", "definition": "1938년 나치 돌격대가 독일 전역의 유대인 상점과 회당(시나고그)을 불태우고 파괴한 잔혹한 학살 사건."},
    {"id": "wh9_25", "level": 9, "term": "게슈타포", "definition": "비밀리에 반체제 인사와 유대인을 감시하고 영장 없이 체포·고문했던 악명 높은 나치 비밀경찰."},
    {"id": "wh9_26", "level": 9, "term": "프랑코", "definition": "군부 쿠데타를 일으켜 스페인 내전을 승리로 이끌고 수십 년간 스페인을 지배한 우익 군부 독재자."},
    {"id": "wh9_27", "level": 9, "term": "게르니카", "definition": "스페인 내전 때 독일 콘도르 군단의 무차별 민간인 폭격을 피카소가 흑백의 분노로 고발한 대작."},
    {"id": "wh9_28", "level": 9, "term": "만주사변", "definition": "1931년 일본 관동군이 류탸오후 철도를 폭파하고 만주를 불법 침략하여 괴뢰 만주국을 세운 사건."},
    {"id": "wh9_29", "level": 9, "term": "중일전쟁", "definition": "1937년 노구교 사건을 구실로 일본이 중국 본토를 전면 침략하여 난징대학살 등을 저지른 전쟁."},
    {"id": "wh9_30", "level": 9, "term": "군국주의", "definition": "군사력 강화와 대외 정복을 국가의 최고 목적으로 삼고 군부가 정치 권력을 완전히 장악함."},
    {"id": "wh9_31", "level": 9, "term": "삼국군사동맹", "definition": "독일, 이탈리아, 일본이 침략 야욕을 위해 맺은 추축국(Axis) 군사 동맹 조약."},

    # Lv.10 (+21)
    {"id": "wh10_11", "level": 10, "term": "폴란드침공", "definition": "1939년 9월 1일 나치 독일이 선전포고 없이 폴란드를 기습 공격하여 제2차 세계대전이 발발함."},
    {"id": "wh10_12", "level": 10, "term": "전격전", "definition": "탱크 기갑부대와 공군 급강하 폭격기의 합동 공격으로 적의 방어선을 초고속으로 무너뜨린 나치 전법."},
    {"id": "wh10_13", "level": 10, "term": "진주만공습", "definition": "1941년 12월 7일 일본 해군 함재기들이 하와이 미 태평양함대 기지를 기습 폭격해 태평양전쟁이 시작됨."},
    {"id": "wh10_14", "level": 10, "term": "미드웨이해전", "definition": "암호를 해독한 미 해군이 일본 항공모함 4척을 격침시키며 태평양 전선의 전세를 역전시킨 결정적 해전."},
    {"id": "wh10_15", "level": 10, "term": "스탈린그라드", "definition": "소련군이 200일간의 처절한 시가전 끝에 독일 제6군을 전멸시키며 동부 전선의 승패를 가른 격전."},
    {"id": "wh10_16", "level": 10, "term": "노르망디상륙", "definition": "1944년 6월 6일 아이젠하워 지휘하에 연합군이 프랑스 북부 해안에 상륙하여 파리를 해방시킨 작전."},
    {"id": "wh10_17", "level": 10, "term": "홀로코스트", "definition": "나치 정권이 가스실과 강제수용소를 이용해 유럽 유대인 600만 명을 조직적으로 학살한 만행."},
    {"id": "wh10_18", "level": 10, "term": "아우슈비츠", "definition": "폴란드에 위치하며 매일 수천 명의 유대인이 독가스로 학살당한 최악의 나치 강제절멸수용소."},
    {"id": "wh10_19", "level": 10, "term": "얄타회담", "definition": "1945년 2월 루스벨트, 처칠, 스탈린이 모여 독일의 전후 분할 점령과 소련의 대일 참전을 비밀 합의함."},
    {"id": "wh10_20", "level": 10, "term": "원자폭탄", "definition": "미국 맨해튼 프로젝트로 개발되어 히로시마와 나가사키에 투하되어 일본의 항복을 받아낸 핵무기."},
    {"id": "wh10_21", "level": 10, "term": "뉘른베르크재판", "definition": "전후 나치 독일의 주요 전범들을 인도에 반한 죄, 평화에 반한 죄로 기소하여 처벌한 국제재판."},
    {"id": "wh10_22", "level": 10, "term": "국제연합", "definition": "국제연맹의 실패를 교훈 삼아 5대 상임이사국의 거부권과 군사력을 갖추고 창설된 유엔(UN)."},
    {"id": "wh10_23", "level": 10, "term": "트루먼독트린", "definition": "1947년 공산주의의 팽창을 막기 위해 자유민주주의 진영을 전면 지원하겠다고 선언한 봉쇄 정책."},
    {"id": "wh10_24", "level": 10, "term": "마셜플랜", "definition": "전쟁으로 폐허가 된 서유럽의 경제 부흥과 공산화 방지를 위해 미국이 130억 달러를 쏟아부은 원조."},
    {"id": "wh10_25", "level": 10, "term": "베를린봉쇄", "definition": "1948년 소련이 서베를린의 육로와 수로를 차단하자 미국이 1년간 대규모 항공 수송 작전으로 맞섬."},
    {"id": "wh10_26", "level": 10, "term": "북대서양조약기구", "definition": "소련의 군사적 위협에 대항하여 미국과 서유럽 국가들이 창설한 집단 안보 동맹(NATO)."},
    {"id": "wh10_27", "level": 10, "term": "바르샤바조약기구", "definition": "나토에 맞서 소련과 동유럽 공산 위성국가들이 결성한 군사 동맹 기구(WTO)."},
    {"id": "wh10_28", "level": 10, "term": "쿠바미사일위기", "definition": "1962년 소련이 쿠바에 핵미사일 배치를 시도하자 케네디가 해상 봉쇄를 단행해 핵전쟁 직전까지 감."},
    {"id": "wh10_29", "level": 10, "term": "베를린장벽", "definition": "동독 공산 정권이 동베를린 주민들의 서베를린 탈출을 막기 위해 쌓았던 냉전 분단의 콘크리트 상징."},
    {"id": "wh10_30", "level": 10, "term": "페레스트로이카", "definition": "고르바초프 서기장이 침체된 소련을 개혁하기 위해 추진한 경제 개편과 개방(글라스노스트) 정책."},
    {"id": "wh10_31", "level": 10, "term": "소련해체", "definition": "1991년 12월 15개 공화국으로 분리 독립하며 동서 냉전 체제가 종식되고 소비에트 연방이 공식 소멸함."}
